@@ -0,0 +1,39 @@
+import { memoryStore } from "../db/store.js";
+import { AppError } from "../errors.js";
+import { isDate } from "../dates.js";
+import { t } from "../i18n/messages.js";
+import { getRecipe, scaled } from "./recipes.js";
+import { consume } from "./batches.js";
+
+/** Imports sale rows atomically, retaining ingredient snapshots for reporting. */
+export function importSales(store, rows) {
+  const staged = memoryStore(store.data);
+  const existing = new Set(staged.data.sales.map((s) => s.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (const row of rows) {
+    try {
+      const { ticket, soldAt, dishId, qty } = row;
+      if (!ticket) throw new AppError("bad_request", { reason: "ticket is required" });
+      if (!/^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)$/.test(soldAt) ||
+          !isDate(soldAt.slice(0, 10)) || !Number.isFinite(Date.parse(soldAt)))
+        throw new AppError("bad_request", { reason: "soldAt must be an ISO instant" });
+      if (!Number.isSafeInteger(qty) || qty < 1) throw new AppError("invalid_qty");
+      const dish = staged.data.dishes.find((d) => d.id === dishId);
+      if (!Number.isSafeInteger(dishId) || !dish) throw new AppError("bad_request", { reason: "unknown dish" });
+      const ingredients = scaled(getRecipe(staged, dish.recipeId), qty);
+      if (ingredients.some((i) => !Number.isFinite(i.qty) || i.qty <= 0)) throw new AppError("invalid_qty");
+      if (existing.has(ticket)) continue;
+      for (const ingredient of ingredients)
+        consume(staged, ingredient.itemId, ingredient.qty, { at: new Date(soldAt).toISOString(), ref: `sale:${ticket}` });
+      staged.data.sales.push({ ticket, soldAt: new Date(soldAt).toISOString(), dishId, qty, ingredients });
+      tickets.add(ticket);
+      dishes += qty;
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      throw new AppError("sales_row", { row: row.row, reason: t(error.code, "en", error.params) });
+    }
+  }
+  store.data = staged.data;
+  return { tickets: tickets.size, dishes };
+}
