+++ b/src/io/sales-import.js
@@ -0,0 +1,28 @@
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+import { importSales } from "../domain/sales.js";
+
+/** Parses sales CSV and imports the whole file atomically. */
+export function importSalesCsv(store, text) {
+  const lines = text.split(/\r?\n/);
+  const rows = [];
+  let header;
+  for (const [index, line] of lines.entries()) {
+    if (!line.trim()) continue;
+    if (!/^(?:"(?:[^"]|"")*"|[^",]*)(?:,(?:"(?:[^"]|"")*"|[^",]*))*$/.test(line))
+      throw new AppError("sales_row", { row: index + 1, reason: "malformed CSV" });
+    const fields = parseCsv(line)[0].map((s) => s.trim());
+    if (!header) {
+      header = fields;
+      if (header.length !== 4 || new Set(header).size !== 4 ||
+          !["ticket", "soldAt", "dishId", "qty"].every((key) => header.includes(key)))
+        throw new AppError("sales_row", { row: index + 1, reason: "expected ticket,soldAt,dishId,qty columns" });
+      continue;
+    }
+    if (fields.length !== 4) throw new AppError("sales_row", { row: index + 1, reason: "expected four fields" });
+    const row = Object.fromEntries(header.map((key, i) => [key, fields[i]]));
+    rows.push({ ...row, dishId: Number(row.dishId), qty: Number(row.qty), row: index + 1 });
+  }
+  if (!header) throw new AppError("sales_row", { row: 1, reason: "missing header" });
+  return importSales(store, rows);
+}
